@startuml

class SmartHome {
  + physicalAddress : string
}

class User {
  + name : string
}

class Room {}

abstract class Device {
  + deviceID : int
}

class Sensor extends Device {}

class Actuator extends Device {}

class SensorReading {
  + value : double
  + timestamp : time
}

class ControlCommand {
  + command : string
  + timestamp : time
  + status : string
}

class ActivityLog {}

class AutomationRule {
  + ruleStatus : RuleStatus
}

class Precondition {}

class Action {}

class TriggerRecord {
  + timestamp : time
}

enum RuleStatus {
  created
  edited
  activated
  deactivated
}

SmartHome "1" -- "1" SmartHome : located at
SmartHome "1" *-- "*" Room
SmartHome "1" *-- "0..*" Sensor
SmartHome "1" *-- "0..*" Actuator
SmartHome "1" *-- "0..*" ActivityLog
SmartHome "1" *-- "0..*" AutomationRule
SmartHome "1" *-- "0..*" TriggerRecord

User "1" -- "*" SmartHome : manages
User "1" -- "*" AutomationRule : creates

Room "1" *-- "*" Sensor
Room "1" *-- "*" Actuator

Sensor "1" -- "*" SensorReading
Actuator "1" -- "*" ControlCommand

AutomationRule "1" *-- "1" Precondition
AutomationRule "1" *-- "1" Action
AutomationRule "0..1" -- "0..1" AutomationRule : depends on
AutomationRule "0..1" -- "0..1" AutomationRule : conflicts with

ActivityLog "1" *-- "*" SensorReading
ActivityLog "1" *-- "*" ControlCommand

TriggerRecord "*" -- "1" AutomationRule

@enduml

